import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design system colors
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // Plate geometry parameters
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const platePitch = 1.5; // vertical spacing (1.5 = 6 × 0.25 base unit)
  const columnOffsetX = 0.9;
  const plateCount = 6;
  const columnLoopDist = 9.0; // seamless modulo wrap distance
  const bevelThickness = 0.03;
  const accentStripWidth = 0.03;

  // Load texture
  const imageUrl = config.assets?.[0]?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const baseTexture = ctx.textureLoader.load(imageUrl);
  baseTexture.colorSpace = THREE.SRGBColorSpace;

  // Scrollable plate container
  const plateGroup = new THREE.Group();
  const plates = [];
  const captions = [];

  // Build 6 image plates with bevels and accents
  for (let i = 0; i < plateCount; i++) {
    // Main plate geometry
    const plateGeom = new THREE.PlaneGeometry(plateWidth, plateHeight);
    const plateMat = new THREE.MeshStandardMaterial({
      map: baseTexture,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });

    const plateMesh = new THREE.Mesh(plateGeom, plateMat);
    plateMesh.position.set(columnOffsetX, i * platePitch, 0);
    plateGroup.add(plateMesh);
    plates.push(plateMesh);

    // Bevel frame (machined ink edges)
    const bevelMat = new THREE.MeshStandardMaterial({
      color: colors.ink,
      roughness: 0.5,
      metalness: 0.5
    });

    // Top edge
    const topBevel = new THREE.Mesh(
      new THREE.PlaneGeometry(plateWidth + 2 * bevelThickness, bevelThickness),
      bevelMat
    );
    topBevel.position.set(0, plateHeight / 2 + bevelThickness / 2, -0.001);
    plateMesh.add(topBevel);

    // Bottom edge
    const bottomBevel = new THREE.Mesh(
      new THREE.PlaneGeometry(plateWidth + 2 * bevelThickness, bevelThickness),
      bevelMat
    );
    bottomBevel.position.set(0, -plateHeight / 2 - bevelThickness / 2, -0.001);
    plateMesh.add(bottomBevel);

    // Left edge
    const leftBevel = new THREE.Mesh(
      new THREE.PlaneGeometry(bevelThickness, plateHeight),
      bevelMat
    );
    leftBevel.position.set(-plateWidth / 2 - bevelThickness / 2, 0, -0.001);
    plateMesh.add(leftBevel);

    // Right edge
    const rightBevel = new THREE.Mesh(
      new THREE.PlaneGeometry(bevelThickness, plateHeight),
      bevelMat
    );
    rightBevel.position.set(plateWidth / 2 + bevelThickness / 2, 0, -0.001);
    plateMesh.add(rightBevel);

    // Accent strip (left edge, emissive signal-red)
    const accentMat = new THREE.MeshStandardMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.4,
      roughness: 0.5,
      metalness: 0.2
    });

    const accentStrip = new THREE.Mesh(
      new THREE.PlaneGeometry(accentStripWidth, plateHeight),
      accentMat
    );
    accentStrip.position.set(
      -plateWidth / 2 - bevelThickness - accentStripWidth / 2,
      0,
      0.001
    );
    plateMesh.add(accentStrip);
  }

  group.add(plateGroup);

  // Text rendering via fontAtlas
  const textContent = config.textContent || [];

  // Headline (pinned at [-1.6, 1.9, 0])
  const headline = textContent.find(t => t.type === 'headline');
  if (headline && ctx.fontAtlas?.createTextMesh) {
    const headlineMesh = ctx.fontAtlas.createTextMesh({
      text: headline.content,
      fontSize: 0.4,
      fontFamily: 'Lora',
      fontWeight: 600,
      color: colors.paper,
      anchorX: 'left',
      anchorY: 'top'
    });
    headlineMesh.position.set(-1.6, 1.9, 0);
    group.add(headlineMesh);
  }

  // Captions (one per plate, fade in/out with focus)
  const captionItems = textContent.filter(t => t.type === 'caption');
  captionItems.forEach((caption, idx) => {
    if (ctx.fontAtlas?.createTextMesh) {
      const captionMesh = ctx.fontAtlas.createTextMesh({
        text: caption.content,
        fontSize: 0.12,
        fontFamily: 'JetBrains Mono',
        fontWeight: 400,
        color: colors.paper,
        anchorX: 'left',
        anchorY: 'center'
      });
      captionMesh.position.set(-1.6, idx * platePitch, 0.01);
      if (captionMesh.material) {
        captionMesh.material.opacity = 0;
        captionMesh.material.transparent = true;
      }
      captions.push(captionMesh);
      plateGroup.add(captionMesh);
    }
  });

  // Scroll animation state
  let scrollPos = 0;
  let scrollSettleTimeout = null;

  // Update focus state: scale + caption opacity for plate nearest y=0
  const updateFocusState = () => {
    plates.forEach((plate, idx) => {
      const plateWorldY = plate.position.y + scrollPos;
      const distFromCenter = Math.abs(plateWorldY);
      const isFocused = distFromCenter < platePitch / 2;

      gsap.to(plate.scale, {
        x: isFocused ? 1.06 : 1.0,
        y: isFocused ? 1.06 : 1.0,
        duration: 0.35,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        overwrite: 'auto'
      });

      if (captions[idx]?.material) {
        gsap.to(captions[idx].material, {
          opacity: isFocused ? 1 : 0,
          duration: 0.35,
          overwrite: 'auto'
        });
      }
    });
  };

  // Scroll handler: 1.5 units per viewport scroll, weighted settle
  group.userData.handlers = {
    onScroll: (event) => {
      clearTimeout(scrollSettleTimeout);
      gsap.killTweensOf(plateGroup.position);

      // Apply scroll (1.5 units per scroll event)
      const scrollDelta = (event.deltaY || 0) * (1.5 / 100);
      let newPos = scrollPos + scrollDelta;

      // Seamless loop wrapping
      while (newPos > columnLoopDist / 2) newPos -= columnLoopDist;
      while (newPos < -columnLoopDist / 2) newPos += columnLoopDist;

      scrollPos = newPos;
      plateGroup.position.y = scrollPos;
      updateFocusState();

      // Weighted-settle: snap to nearest plate after scroll ends
      scrollSettleTimeout = setTimeout(() => {
        const nearestIdx = Math.round(scrollPos / platePitch);
        const targetY = nearestIdx * platePitch;

        gsap.to(plateGroup.position, {
          y: targetY,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          onUpdate: () => {
            scrollPos = plateGroup.position.y;
            updateFocusState();
          }
        });
      }, 120);
    }
  };

  // Apply fly-through cinematic primitive (camera dollies 2.5 units deeper)
  if (ctx.primitives?.['fly-through']) {
    ctx.primitives['fly-through'](group, {
      depthUnits: 2.5,
      trigger: 'scroll'
    });
  }

  // Cleanup: dispose geometries, materials, textures; kill timelines
  group.userData.cleanup = () => {
    clearTimeout(scrollSettleTimeout);
    gsap.killTweensOf([plateGroup.position, ...plates.map(p => p.scale), ...captions.map(c => c.material)]);

    baseTexture.dispose();
    plates.forEach(plate => {
      plate.geometry.dispose();
      plate.material.dispose();
      plate.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });
    captions.forEach(caption => {
      if (caption.geometry) caption.geometry.dispose();
      if (caption.material) caption.material.dispose();
    });
  };

  return group;
}
